using System.Collections;
using Astrea.RunModifiers;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GoldReward", menuName = "Data/Rewards/GoldReward", order = 0)]
public class GoldReward : Reward
{
	private const string starShardsRewardID = "StarShardsReward_D";

	[Header("Save System")]
	[SerializeField]
	private SaveSystem saveSystem;

	[Header("Assets")]
	[SerializeField]
	private int goldAmount;

	[SerializeField]
	private bool gettingGoldOnMap;

	[SerializeField]
	private bool gettingGoldOnEventNoDelay;

	[SerializeField]
	[ShowIf("gettingGoldOnEventNoDelay")]
	private bool dontGoToEndOfBattleState;

	[SerializeField]
	[ShowIf("gettingGoldOnEventNoDelay")]
	private bool goBackToEventsPanel;

	[SerializeField]
	[ShowIf("goBackToEventsPanel")]
	private VoidEvent OnAfterRewardFadeInCanvasAndUpdateEventsPanel;

	private bool goldAmountHigherThanZero => goldAmount > 0;

	public void SetGoldAmount(int goldAmount)
	{
		this.goldAmount = goldAmount;
	}

	public void SetGettingGoldOnEventNoDelay(bool gettingGoldOnEventNoDelay)
	{
		this.gettingGoldOnEventNoDelay = gettingGoldOnEventNoDelay;
	}

	public void SetDontGoToEndOfBattleState(bool value)
	{
		dontGoToEndOfBattleState = value;
	}

	public override string GetRewardName()
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("StarShardsReward_D"), goldAmount);
	}

	public override void GetReward()
	{
		Debug.Log("-----------GET GOLD REWARD------------");
		ReferenceSingleton<CoroutineHandler>.Instance.Run(GetGoldCoroutine());
	}

	private IEnumerator GetGoldCoroutine()
	{
		if (gettingGoldOnMap)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(goldAmount);
			saveSystem.SaveGold(saveAndStoreCache: false);
			yield break;
		}
		if (gettingGoldOnEventNoDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(goldAmount);
			if (goBackToEventsPanel)
			{
				OnAfterRewardFadeInCanvasAndUpdateEventsPanel.Raise();
			}
			else if (!dontGoToEndOfBattleState)
			{
				yield return InvokeAlternatives.WaitOneFrame();
				ReferenceSingleton<GameStateManager>.Instance.EndOfBattleState.GoToMapCoroutineWithoutDelays = true;
				ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
			}
			yield break;
		}
		bool disableRewardsAnimation = ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation;
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		if (goldAmount > 0)
		{
			yield return InvokeAlternatives.WaitForFrames(3);
			if (!ReferenceSingleton<MiscOmensHandler>.Instance.IsCrimsomVaultActive() && ReferenceSingleton<RunModifiersManager>.Instance.StellarHeritageRunModifier == null)
			{
				Debug.Log("-----------GET GOLD REWARD NO CRIMSOMVAULT------------");
				if (!disableRewardsAnimation)
				{
					yield return new WaitForSeconds(0.25f);
				}
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(goldAmount);
				if (!disableRewardsAnimation)
				{
					yield return new WaitForSeconds(1.1f);
				}
				Debug.Log("-----------GET GOLD REWARD GO END OF BATTLE STATE------------");
				ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
			}
			else
			{
				ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
			}
		}
		else
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(goldAmount);
			if (!disableRewardsAnimation)
			{
				yield return new WaitForSeconds(1.1f);
			}
			ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
		}
	}
}
